    require(lease is None and not any(i["status"]=="ACTIVE" for i in q["items"]),"no duplicate/parallel execution")
    require(items[target]["status"]=="PENDING" and all(items[d]["status"]=="PASS" for d in items[target]["depends"]),"completed predecessors required")
    eligible=[i["id"] for i in q["items"] if i["status"]=="PENDING" and all(items[d]["status"]=="PASS" for d in i["depends"])]
