def peel(rel,raw):
    if rel=="AGENTS.md":
        require(raw.count(AGENTS_BOUNDARY)==1,"single AGENTS amendment")
        return raw.split(AGENTS_BOUNDARY,1)[1]
    if rel in META["scope"][1:5]:
        require(raw.count(DOC_BOUNDARY)==1,"single sequence history boundary")
        return raw.split(DOC_BOUNDARY,1)[1]
    role="continuity" if rel=="tools/check-project-continuity-control.py" else "preflight"
    begin=("\n# BEGIN "+META["package"]+" "+role+"\n").encode()
    end=("# END "+META["package"]+" "+role+"\n").encode()
    require(raw.count(begin)==raw.count(end)==1,"one additive profile block")
    a=raw.index(begin);b=raw.index(end,a)+len(end)
    old=raw[:a]+raw[b:]
    # Generator adds one extra newline before main in addition to the original one.
    dispatch=(b'    if development_sequence_requested():\n        return run_development_sequence("continuity")\n' if role=="continuity" else b'    if _development_sequence_preflight():\n        return\n')
    require(old.count(dispatch)==1,"one bounded profile dispatch")
    old=old.replace(dispatch,b"",1)
    marker=b"\n\ndef main()"
    require(marker in old,"original main boundary")
    return old.replace(marker,b"\ndef main()",1)
def tree(ref):
    rows={}
    for row in git("ls-tree","-rz","--full-tree",ref).split(b"\0"):
        if not row:continue
        meta,name=row.split(b"\t",1);mode,kind,oid=meta.decode().split()
        require(kind=="blob" and name.decode() not in rows,"regular unique tree")
        rows[name.decode()]=[mode,oid]
    return rows
# Additive successor protection for the fixed personally confirmed W01-W08 family.
def validate_active_manifest(q):
    validate_queue(q)
    current=q["current"];require(current in META["order"],"known active queue position")
    active=q["active"];paths=active["paths"]
    require(active["task"]=="ACCAOUI_DEVELOPMENT_SEQUENCE_"+current,"exact active task identity")
    require(re.fullmatch("[0-9a-f]{40}",active["baseline"]) and type(paths) is list and paths and len(paths)==len(set(paths)),"one exact baseline/path manifest")
    require(type(active["attempt"]) is int and active["attempt"]>=1 and type(active["correctionRounds"]) is int and active["correctionRounds"]>=0 and (has_v2(q) or active["correctionRounds"]<=2),"bounded active counters")
    require(active["fullFeatureScopeRetained"] is True,"full feature objective retained")
    require(sum(i["status"]=="ACTIVE" for i in q["items"])==1 and next(i for i in q["items"] if i["id"]==current)["status"]=="ACTIVE","one active task only")
    lookup={i["id"]:i for i in q["items"]}
    require(not any(i["status"]=="STOPP" for i in q["items"]) and all(lookup[d]["status"]=="PASS" for d in lookup[current]["depends"]),"no protection STOPP or incomplete dependency")
    common={"docs/tasks/CURRENT_TASK.md","docs/PROJECT_STATE_CURRENT.md","docs/PROJECT_MASTERLIST.md","docs/CURSOR_MASTER_CONTEXT_ACCAOUI.md","docs/tasks/DEVELOPMENT_QUEUE_V1.json"}
    require(common<=set(paths),"current canonical/queue binding required")
    exact_roots={"app.js","index.html","style.css","oral-exam.js","oral-exam.css","oral-sheets-v23.js","patch-v21.js"}
    frozen={"AGENTS.md","tools/check-project-continuity-control.py","tools/preflight.py","tools/check-development-queue-v1.py","tools/check-written-timeout-reacceptance-contract-v1.py","docs/WRITTEN_TIMEOUT_REACCEPTANCE_CONTRACT_V1.md",AUDIT}
    for rel in paths:
        require(type(rel) is str and rel and "\\" not in rel and not rel.startswith("/") and ".." not in Path(rel).parts and ":" not in rel,"regular relative manifest path")
        if current=="W00":
            require(rel in META["scope"],"closed W00 scope")
            continue
        if has_v2(q) and rel in V2_RULE_PATHS:continue
        require(rel not in frozen,"old checker/rule/audit outside successor scope")
        if rel in common:continue
        test=rel.startswith("tools/") and rel.endswith((".py",".js",".json")) and Path(rel).name.startswith(("check-","test-","capture-","run-","written-timeout-"))
        status=rel.startswith("docs/") and rel.endswith(".md") and ("ACCEPTANCE" in rel or "TEST" in rel or "REPORT" in rel or "READINESS" in rel or "GOLIVE" in rel)
        if current=="W01":
            require(test and any(token in Path(rel).name for token in ("written-timeout","natural-written","written-natural")),"W01 evidence/test tools only; no timer/product edits")
        elif current=="W02":
            oral=rel.startswith("data/oral-") and rel.endswith(".js") and rel in META["initialTree"] and rel in (ROOT/"index.html").read_text(encoding="utf-8")
            require(rel in exact_roots or oral or test or status,"W02 existing product family without question/solution edits")
        elif current=="W03":
            require(rel in exact_roots or (rel.startswith("data/") and rel.endswith(".js") and Path(rel).name.startswith(("supabase-","auth-","participant-","account-","course-","progress-","session-"))) or (rel.startswith("supabase/migrations/") and rel.endswith(".sql")) or test or status or rel=="docs/SUPABASE_EXAM_QUESTION_DATABASE_PLAN.md","W03 auth/progress family")
        elif current=="W04":
            require(rel in exact_roots|{"docs/LEARNING_STRATEGY_MODULE.md"} or (rel.startswith("data/") and rel.endswith(".js") and Path(rel).name.startswith(("learning-","study-","progress-","spaced-","recall-","reminder-"))) or test or status,"W04 learning guidance family")
        elif current=="W05":
            require(rel in exact_roots|{"questions.json"} or (rel.startswith("data/") and rel.endswith((".js",".json"))) or (rel.startswith("supabase/migrations/") and rel.endswith(".sql")) or test or status,"W05 content/admin family, fachliche Freigabe separate")
        elif current=="W06":
            require(rel in exact_roots or (rel.startswith("data/") and rel.endswith((".js",".json")) and Path(rel).name.startswith(("material-","document-","certificate-","export-","notification-","message-","training-"))) or (rel.startswith("supabase/migrations/") and rel.endswith(".sql")) or test or status,"W06 material/certificate/export family")
        elif current=="W07":
            require(rel in exact_roots or (rel.startswith("data/") and rel.endswith((".js",".json")) and Path(rel).name.startswith(("ai-","learning-ai-","tutor-"))) or test or status,"W07 local AI boundary, provider decision separate")
        elif current=="W08":require(test or status,"W08 acceptance/release dossier, no production")
    evidence=Path(active["evidenceDirectory"]).resolve()
    require(evidence.is_relative_to(OUT.parent.resolve()) and evidence!=OUT.parent.resolve(),"private external package evidence")
    return active

def validate_v2_source_bindings(q,m,baseline):
    if not has_v2(q):return
    require(m.get("workAuthorityV2")==V2_AUTHORITY and bool(m.get("diagnosticPurpose","").strip()),"pinned direct V2 authority and concrete diagnostic purpose")
    begin=b"<!-- BEGIN PERSONALLY CONFIRMED WORK_AUTHORITY_V2 -->\n"
    end=b"\n<!-- END PERSONALLY CONFIRMED WORK_AUTHORITY_V2 -->"
    text=(ROOT/"docs/DEVELOPMENT_SEQUENCE_V1.md").read_bytes()
    require(text.count(begin)==text.count(end)==1,"one complete V2 source")
    source=text.split(begin,1)[1].split(end,1)[0]
    require(len(source)==V2_AUTHORITY["textBytes"] and sha(source)==V2_AUTHORITY["textSHA256"],"complete unchanged personally confirmed V2 text")
    boundary=("\n## Unveränderte Historie vor "+V2_AUTHORITY["package"]+"\n\n---\n\n").encode()
    for rel in ("AGENTS.md","docs/DEVELOPMENT_SEQUENCE_V1.md"):
        data=(ROOT/rel).read_bytes()
        require(V2_AUTHORITY["messageId"].encode() in data.split(boundary,1)[0],"direct V2 source in canonical rules")
        if rel in m["scope"]:
            require(data.count(boundary)==1 and blob(data.split(boundary,1)[1])==baseline[rel][1],"original rule history preserved "+rel)
    if "tools/check-development-queue-v1.py" in m["scope"]:
        old=ast.parse(git("show",m["base"]+":tools/check-development-queue-v1.py").decode("utf-8"))
        new=ast.parse((ROOT/"tools/check-development-queue-v1.py").read_bytes().decode("utf-8"))
        allowed={"validate_queue","queue_cases","validate_active_manifest","successor_protection","has_v2","validate_v2_source_bindings","validate_second_run_authority"}
        functions=lambda tree:{n.name:ast.dump(n,include_attributes=False) for n in tree.body if isinstance(n,ast.FunctionDef) and n.name not in allowed}
        require(functions(old)==functions(new),"all original non-authority functions and full original runner preserved")
        for name in ("META","GATE_SOURCE","HISTORICAL_FUNCTION"):
            get=lambda tree:next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id==name for t in n.targets))
            require(ast.dump(get(old),include_attributes=False)==ast.dump(get(new),include_attributes=False),"unchanged original factual/check/budget source "+name)

