    manifest=json.loads(raw)
    require(manifest["task"]==META["task"] and manifest["base"]==META["base"] and manifest["scope"]==META["scope"] and manifest["before"]==META["before"],"closed W00 application manifest")
    require(git("rev-parse","--is-inside-work-tree").strip()==b"true" and Path(git("rev-parse","--show-toplevel").decode().strip()).resolve()==ROOT.resolve(),"real exact worktree")
    require(ROOT.resolve()==Path(r"C:\xampp\htdocs\accaoui\v4-dashboard") and git("branch","--show-current").strip()==b"main","existing WORK main")
    require(git("remote","get-url","origin").strip()==b"https://github.com/asarrad-bit/accaoui-34a-lernapp.git","fixed origin")
    require(git("rev-parse","--is-shallow-repository").strip()==b"false" and not git("replace","-l").strip(),"complete unreplaced history")
