        print("HISTORICAL_GATE_SYNTHETIC_CASES: "+json.dumps(cases),flush=True)
        require(sha(HISTORICAL_FUNCTION.encode())==META["embeddedHistoricalFunctionSHA256"],"bounded historical read binding")
        namespace=dict(control)
        exec(compile(HISTORICAL_FUNCTION,"<preserved-original-contracts-with-historical-source-bindings>","exec"),namespace)
        gate["OUT"]=OUT
