        print("DEVELOPMENT_SEQUENCE_CURRENT_PASS: "+kind+"; phase="+before["phase"],flush=True)
        print("Original full checks retained; v27.37n STOPP / NOT VERIFIED; historical fixtures are not a real 7200s acceptance; see actual active package evidence; Supabase NICHT LIVE.",flush=True)
